function perfectpixel_atc_clicks_script() {
	if ( ! function_exists( 'is_product' ) || ! is_product() ) {
		return;
	}
	$data = array(
		'url' => admin_url( 'admin-ajax.php' ),
		'id'  => get_queried_object_id(),
	);
	?>
	<script>
	( function () {
		var cfg = <?php echo wp_json_encode( $data ); ?>;
		document.addEventListener( 'click', function ( e ) {
			if ( ! e.target.closest( '.single_add_to_cart_button' ) ) {
				return;
			}
			var body = new FormData();
			body.append( 'action', 'perfectpixel_atc_click' );
			body.append( 'product_id', cfg.id );
			navigator.sendBeacon ? navigator.sendBeacon( cfg.url, body ) : fetch( cfg.url, { method: 'POST', body: body, keepalive: true } );
		} );
	} )();
	</script>
	<?php
}

function perfectpixel_atc_clicks_record() {
	$product_id = isset( $_POST['product_id'] ) ? absint( $_POST['product_id'] ) : 0;
	if ( $product_id && 'product' === get_post_type( $product_id ) ) {
		update_post_meta( $product_id, '_perfectpixel_atc_clicks', (int) get_post_meta( $product_id, '_perfectpixel_atc_clicks', true ) + 1 );
	}
	wp_die();
}

function perfectpixel_atc_clicks_column( $columns ) {
	$columns['perfectpixel_atc_clicks'] = 'Κλικ καλαθιού';
	return $columns;
}

function perfectpixel_atc_clicks_column_value( $column, $post_id ) {
	if ( 'perfectpixel_atc_clicks' === $column ) {
		echo (int) get_post_meta( $post_id, '_perfectpixel_atc_clicks', true );
	}
}
